// Validate Queue Settings before any SQL uses them (table names go into the SQL text).
const s = $input.first().json;
const problems = [];
const ident = /^[a-z_][a-z0-9_]{0,50}$/;
for (const k of ['queue_table', 'dead_letter_table']) if (!ident.test(String(s[k] ?? '').trim())) problems.push(k + ' must be a lowercase table name (letters, digits, _)');
if (String(s.queue_table).trim() === String(s.dead_letter_table).trim()) problems.push('queue_table and dead_letter_table must differ');
const int = (k, min, max) => { const v = Number(s[k]); if (!Number.isInteger(v) || v < min || v > max) problems.push(k + ' must be a whole number from ' + min + ' to ' + max); };
int('batch_size', 1, 100); int('max_attempts', 1, 50); int('retry_base_seconds', 1, 86400); int('retry_max_seconds', 1, 604800); int('lease_minutes', 1, 1440);
if (Number(s.retry_max_seconds) < Number(s.retry_base_seconds)) problems.push('retry_max_seconds must be at least retry_base_seconds');
if (!/^https?:\/\/\S+$/.test(String(s.worker_url ?? '').trim())) problems.push('worker_url must start with http:// or https://');
const email = /^[^\s@<>]+@[^\s@<>]+\.[^\s@<>]+$/;
for (const a of String(s.digest_to ?? '').split(',')) if (!email.test(a.trim())) problems.push('digest_to has an invalid address: "' + a.trim() + '"');
const from = String(s.digest_from ?? '').trim(); const fromAddr = (from.match(/<([^>]+)>$/) || [null, from])[1];
if (!email.test(fromAddr)) problems.push('digest_from must be an email address');
return [{ json: { ok: problems.length === 0, problems } }];

