WITH stuck AS (
  SELECT id FROM {{ $('Queue Settings').first().json.queue_table }} WHERE status = 'processing' AND locked_until < now() FOR UPDATE SKIP LOCKED
), dead AS (
  INSERT INTO {{ $('Queue Settings').first().json.dead_letter_table }} (job_id, job_type, payload, attempts, last_error, job_created_at)
  SELECT id, job_type, payload, attempts, 'Lease ran out before this attempt recorded a result', created_at
  FROM {{ $('Queue Settings').first().json.queue_table }} WHERE id IN (SELECT id FROM stuck) AND attempts >= $1::int
  RETURNING job_id
), removed AS (
  DELETE FROM {{ $('Queue Settings').first().json.queue_table }} WHERE id IN (SELECT job_id FROM dead) RETURNING id
), released AS (
  UPDATE {{ $('Queue Settings').first().json.queue_table }} SET status = 'queued', claim_token = NULL, locked_until = NULL, run_after = now(), updated_at = now(),
    last_error = 'Lease ran out before this attempt recorded a result'
  WHERE id IN (SELECT id FROM stuck) AND attempts < $1::int
  RETURNING id
)
SELECT (SELECT count(*) FROM released)::int AS released, (SELECT count(*) FROM removed)::int AS dead_lettered;

UPDATE {{ $('Queue Settings').first().json.queue_table }} SET status = 'done', claim_token = NULL, locked_until = NULL, last_error = NULL, finished_at = now(), updated_at = now()
WHERE id = $1::bigint AND claim_token = $2::uuid
RETURNING id AS job_id, status;

WITH job AS (
  SELECT * FROM {{ $('Queue Settings').first().json.queue_table }} WHERE id = $1::bigint AND claim_token = $2::uuid FOR UPDATE
), dead AS (
  INSERT INTO {{ $('Queue Settings').first().json.dead_letter_table }} (job_id, job_type, payload, attempts, last_error, job_created_at)
  SELECT id, job_type, payload, attempts, $3, created_at FROM job WHERE attempts >= $4::int
  RETURNING job_id
), removed AS (
  DELETE FROM {{ $('Queue Settings').first().json.queue_table }} WHERE id IN (SELECT job_id FROM dead) RETURNING id
), retry AS (
  UPDATE {{ $('Queue Settings').first().json.queue_table }} AS q SET status = 'queued', claim_token = NULL, locked_until = NULL, last_error = $3, updated_at = now(),
    run_after = now() + make_interval(secs => LEAST($5::double precision * power(2, q.attempts - 1), $6::double precision))
  FROM job WHERE q.id = job.id AND job.attempts < $4::int
  RETURNING q.id, q.run_after
)
SELECT $1::bigint AS job_id, (SELECT count(*) FROM removed)::int AS dead_lettered, (SELECT run_after FROM retry) AS next_try_at;

