// One digest email for all dead letters not reported yet. Every value is HTML-escaped.
const esc = (v) => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');
const rows = $input.all().map((i) => i.json);
const tr = rows.map((r) => '<tr><td>' + esc(r.job_id) + '</td><td>' + esc(r.job_type) + '</td><td>' + esc(r.attempts) + '</td><td>' + esc(r.last_error) + '</td><td><code>' + esc(String(r.payload).slice(0, 300)) + '</code></td></tr>').join('');
const html = '<p>' + rows.length + ' job(s) used all their attempts and were moved to the dead-letter table <b>' + esc($('Queue Settings').first().json.dead_letter_table) + '</b>.</p>'
  + '<table border="1" cellpadding="4" cellspacing="0"><tr><th>Job id</th><th>Type</th><th>Attempts</th><th>Last error</th><th>Payload</th></tr>' + tr + '</table>';
return [{ json: { ids: rows.map((r) => Number(r.id)), count: rows.length, subject: rows.length + ' job(s) moved to the dead-letter table', html } }];
